package com.mg.fixturecockpitsim;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.Locale;
/** AVM-10 airport world: deeper hangar, real-looking buildings/terrain/water/sky, RWY27 motion and centered final. */
public final class RunwayHudView extends View{
 private final Paint f=new Paint(3),l=new Paint(3);private final Path p=new Path();private volatile float altitudeM,speedMps,route,groundProgress,headingDeg;private volatile boolean onGround,demoMode;private volatile String phase="";private float scroll,runwayMeters;private long last;
 public RunwayHudView(Context c){super(c);setWillNotDraw(false);f.setStyle(Paint.Style.FILL);l.setStyle(Paint.Style.STROKE);l.setStrokeCap(Paint.Cap.ROUND);}
 public void setDemoMode(boolean e){demoMode=e;postInvalidateOnAnimation();}public void setDemoProgress(double s){route=(float)Math.max(0,s);postInvalidateOnAnimation();}public void setGroundProgress(double q,double hdg){groundProgress=(float)Math.max(0,Math.min(1,q));headingDeg=(float)hdg;postInvalidateOnAnimation();}public void setFlightState(double a,double s,boolean g,String ph){altitudeM=(float)Math.max(0,a);speedMps=(float)Math.max(0,s);onGround=g;phase=ph==null?"":ph;postInvalidateOnAnimation();}
 protected void onDraw(Canvas c){super.onDraw(c);long n=System.nanoTime();float dt=last==0?.016f:Math.min(.05f,(n-last)/1e9f);last=n;scroll=(scroll+speedMps*dt*.055f)%1f;if(phase.contains("TAKEOFF")||phase.contains("ROLLOUT"))runwayMeters+=speedMps*dt;if(phase.contains("HANGAR_START")||phase.contains("RUNWAY_HOLD"))runwayMeters=0;int w=getWidth(),h=getHeight();float hz=h*(.46f+.075f*Math.min(1,altitudeM/1300));sky(c,w,h,hz);
  if(phase.contains("HANGAR")){hangar(c,w,h,hz);return;}airport(c,w,h,hz);
  if(phase.contains("TAXI")){taxi(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}
  if(demoMode&&phase.contains("ORBIT")){scenery(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}
  if(onGround||phase.contains("RUNWAY")||phase.contains("TAKEOFF")||phase.contains("ROTATE")||phase.contains("APPROACH")||phase.contains("FLARE")||phase.contains("ROLLOUT"))runway(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();}
 private void sky(Canvas c,int w,int h,float hz){f.setShader(new LinearGradient(0,0,0,hz,0xff07182b,0xff77a9c6,Shader.TileMode.CLAMP));c.drawRect(0,0,w,hz,f);f.setShader(null);f.setColor(0x22ffffff);for(int i=0;i<6;i++){float x=w*(.04f+i*.18f),y=hz*(.13f+(i%3)*.05f),ww=w*(.12f+(i%2)*.04f);c.drawOval(x,y,x+ww,y+hz*.035f,f);c.drawOval(x+ww*.18f,y-hz*.015f,x+ww*.62f,y+hz*.025f,f);}f.setColor(0x16fff1c9);c.drawCircle(w*.82f,hz*.18f,w*.055f,f);}
 private void hangar(Canvas c,int w,int h,float hz){float q=phase.contains("PARK")?1-groundProgress:groundProgress,cx=w*.5f;f.setShader(new LinearGradient(0,0,0,h,0xff101418,0xff282d31,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,f);f.setShader(null);float top=h*.17f,bot=h*.88f,half=w*(.17f+.10f*Math.min(1,q));outside(c,cx-half,top,cx+half,bot,w,h);
  // floor perspective and service lanes
  f.setColor(0xff2e3234);p.reset();p.moveTo(cx-half,bot);p.lineTo(cx+half,bot);p.lineTo(w,h);p.lineTo(0,h);p.close();c.drawPath(p,f);l.setColor(0xffe0bc24);l.setStrokeWidth(4);c.drawLine(cx,bot,cx,h,l);l.setColor(0xff596166);l.setStrokeWidth(2);for(int i=1;i<8;i++){float x=w*i/8f;c.drawLine(x,h,cx+(x-cx)*.30f,bot,l);}
  // steel portal frames
  l.setColor(0xff59636a);l.setStrokeWidth(6);for(int i=0;i<7;i++){float t=i/6f,y=lerp(h*.06f,bot,t);float lh=lerp(w*.47f,half,t);c.drawLine(cx-lh,y,cx-lh,bot,l);c.drawLine(cx+lh,y,cx+lh,bot,l);c.drawLine(cx-lh,y,cx+lh,y,l);}l.setStrokeWidth(3);for(int i=0;i<11;i++){float x=w*i/10f;c.drawLine(x,0,cx+(x-cx)*.34f,top,l);}f.setColor(0xffffe8a2);for(int i=0;i<8;i++){float x=w*(.12f+i*.11f);c.drawRoundRect(x,h*.08f,x+w*.055f,h*.095f,5,5,f);}
  // realistic wall equipment
  for(int s=-1;s<=1;s+=2){float base=s<0?w*.045f:w*.86f;f.setColor(0xff3e474c);c.drawRect(base,h*.57f,base+w*.09f,h*.78f,f);f.setColor(0xffd89b2b);c.drawRect(base+w*.012f,h*.61f,base+w*.028f,h*.70f,f);f.setColor(0xff7f8a90);c.drawRect(base+w*.045f,h*.60f,base+w*.078f,h*.68f,f);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(18,w*.019f));c.drawText("HANGAR 01   •   APRON ÇIKIŞI   •   RWY 27",w*.035f,h*.92f,f);}
 private void outside(Canvas c,float x0,float y0,float x1,float y1,int w,int h){f.setShader(new LinearGradient(0,y0,0,y1,0xff79a9c5,0xff385536,Shader.TileMode.CLAMP));c.drawRect(x0,y0,x1,y1,f);f.setShader(null);float cx=(x0+x1)/2;f.setColor(0xff4a4e50);Path r=new Path();r.moveTo(cx-(x1-x0)*.05f,y0+(y1-y0)*.16f);r.lineTo(cx+(x1-x0)*.05f,y0+(y1-y0)*.16f);r.lineTo(x1,y1);r.lineTo(x0,y1);r.close();c.drawPath(r,f);l.setColor(0xffe1c227);l.setStrokeWidth(3);c.drawLine(cx,y0+(y1-y0)*.16f,cx,y1,l);}
 private void taxi(Canvas c,int w,int h,float hz){f.setColor(0xff344735);c.drawRect(0,hz,w,h,f);buildings(c,w,h,hz);float cx=w*.5f,far=w*.045f,near=w*.25f;p.reset();p.moveTo(cx-far,hz+h*.02f);p.lineTo(cx+far,hz+h*.02f);p.lineTo(cx+near,h);p.lineTo(cx-near,h);p.close();f.setColor(0xff454a4c);c.drawPath(p,f);l.setColor(0xffe5c329);l.setStrokeWidth(4);c.drawLine(cx,hz+h*.02f,cx,h,l);for(int i=0;i<18;i++){float z=(i/18f+scroll*.45f)%1f,y=lerp(hz+h*.03f,h,z*z),hh=lerp(far,near,z);f.setColor(0xff438cff);c.drawCircle(cx-hh,y,2+3*z,f);c.drawCircle(cx+hh,y,2+3*z,f);}if(groundProgress>.55f){f.setColor(0xddffffff);f.setTextSize(Math.max(17,w*.018f));c.drawText("RWY 27  •  HOLD SHORT / LINE UP",w*.62f,hz+h*.13f,f);}f.setTextSize(Math.max(14,w*.015f));c.drawText("HDG "+String.format(Locale.US,"%03.0f",norm(headingDeg)),w*.04f,h*.92f,f);}
 private void runway(Canvas c,int w,int h,float hz){float near=1-Math.min(1,altitudeM/1050f);float err=angleError(headingDeg,270f);float cx=w*.5f+clamp(err/30f,-1,1)*w*.13f;float fh=w*(.018f+.012f*near),nh=w*(onGround?.46f:(.12f+.30f*near)),fy=hz+h*.018f,ny=h*(onGround?.998f:(.72f+.26f*near));terrain(c,w,h,hz);p.reset();p.moveTo(cx-fh*1.5f,fy);p.lineTo(cx+fh*1.5f,fy);p.lineTo(cx+nh*1.12f,ny);p.lineTo(cx-nh*1.12f,ny);p.close();f.setColor(0xff686c6c);c.drawPath(p,f);p.reset();p.moveTo(cx-fh,fy);p.lineTo(cx+fh,fy);p.lineTo(cx+nh,ny);p.lineTo(cx-nh,ny);p.close();f.setColor(0xff292d2f);c.drawPath(p,f);
  l.setColor(0xfff5f4ef);l.setStrokeWidth(Math.max(2,w*.0023f));c.drawLine(cx-fh,fy,cx-nh,ny,l);c.drawLine(cx+fh,fy,cx+nh,ny,l);for(int i=-6;i<=6;i++){l.setColor(i%2==0?0x30202020:0x224f4f4f);l.setStrokeWidth(2);c.drawLine(cx+i*fh*.13f,fy,cx+i*nh*.13f,ny,l);}for(int i=0;i<28;i++){float q=(i/28f+scroll)%1f,z=q*q,y=lerp(fy,ny,z);l.setColor(0xffffffff);l.setStrokeWidth(2+13*z);c.drawLine(cx,y,cx,y+5+38*z,l);}for(int i=0;i<24;i++){float q=(i/24f+scroll*.2f)%1f,z=q*q,y=lerp(fy,ny,z),hh=lerp(fh,nh,z);f.setColor(0xffeee9ce);c.drawCircle(cx-hh,y,1+4*z,f);c.drawCircle(cx+hh,y,1+4*z,f);}
  // runway number truly passes beneath the aircraft; distance replaces phase-only animation
  float takeDist=phase.contains("TAKEOFF")?runwayMeters:0;float nz=.54f+takeDist/280f;boolean passed=nz>1.03f;if(!passed){float z=clamp(nz,0,1),y=lerp(fy,ny,z*z),hh=lerp(fh,nh,z);f.setColor(0xffffffff);for(int i=-4;i<=4;i++)if(i!=0)c.drawRect(cx+i*hh*.11f-hh*.035f,y,cx+i*hh*.11f+hh*.035f,y+18+44*z,f);f.setTextAlign(Paint.Align.CENTER);f.setTextSize(Math.max(28,w*(.034f+.028f*z)));c.drawText("27",cx,y+62+38*z,f);f.setTextAlign(Paint.Align.LEFT);}else if(phase.contains("TAKEOFF")){f.setColor(0xff79e37d);f.setTextSize(Math.max(15,w*.016f));c.drawText("✓ RWY 27 EŞİĞİ GEÇİLDİ",w*.71f,h*.91f,f);}if(phase.contains("APPROACH")||phase.contains("FLARE")){f.setColor(Math.abs(err)<3?0xff7fe889:0xffffd35a);f.setTextSize(Math.max(14,w*.015f));c.drawText(Math.abs(err)<3?"FINAL HATTI KİLİTLİ • BURUN RWY 27":"FINAL DÜZELTME • RWY 27",w*.66f,h*.92f,f);} }
 private void terrain(Canvas c,int w,int h,float hz){f.setColor(0xff304632);c.drawRect(0,hz,w,h,f);mountains(c,w,h,hz,.25f,false);buildings(c,w,h,hz);}
 private void airport(Canvas c,int w,int h,float hz){f.setColor(0xff314331);c.drawRect(0,hz,w,hz+h*.12f,f);buildings(c,w,h,hz);}
 private void buildings(Canvas c,int w,int h,float hz){for(int i=0;i<9;i++){float x=w*(.025f+i*.055f),bw=w*(.033f+(i%2)*.012f),bh=h*(.025f+(i%3)*.015f);f.setColor(i%3==0?0xff72797b:0xff555d60);c.drawRect(x,hz-bh,x+bw,hz,f);f.setColor(0x66d9ecff);for(int k=0;k<3;k++)c.drawRect(x+bw*.16f+k*bw*.24f,hz-bh*.72f,x+bw*.27f+k*bw*.24f,hz-bh*.54f,f);}float tx=w*.82f;f.setColor(0xff50595d);c.drawRect(tx-5,hz-h*.09f,tx+5,hz,f);c.drawRect(tx-18,hz-h*.103f,tx+18,hz-h*.083f,f);f.setColor(0xff20272a);c.drawRect(tx-13,hz-h*.101f,tx+13,hz-h*.087f,f);}
 private void scenery(Canvas c,int w,int h,float hz){float t=Math.min(300,route);if(t<45){coast(c,w,h,hz,.30f);label(c,w,h,"SAHİL ÜZERİ TIRMANIŞ");}else if(t<95){mountains(c,w,h,hz,.58f,false);label(c,w,h,"DAĞLARA YAKLAŞMA");}else if(t<150){mountains(c,w,h,hz,.82f,true);label(c,w,h,"VADİ İÇİ UÇUŞ");}else if(t<210){mountains(c,w,h,hz,.96f,true);road(c,w,h,hz);label(c,w,h,"DAĞ YOLU TAKİBİ");}else if(t<255){lake(c,w,h,hz);label(c,w,h,"GÖL / KIYI GEÇİŞİ");}else if(t<280){mountains(c,w,h,hz,.75f,false);label(c,w,h,"YÜKSEK ARAZİ");}else{mountains(c,w,h,hz,.34f,false);airport(c,w,h,hz);label(c,w,h,"RWY 27 İÇİN HİZALANMA");}}
 private void label(Canvas c,int w,int h,String s){f.setColor(0xe8ffffff);f.setTextSize(Math.max(19,w*.020f));c.drawText(s,w*.04f,h*.89f,f);}
 private void mountains(Canvas c,int w,int h,float hz,float scale,boolean valley){mountainLayer(c,w,h,hz,scale*.55f,0xff768786,1.12f,valley);mountainLayer(c,w,h,hz,scale*.76f,0xff526961,1.38f,valley);mountainLayer(c,w,h,hz,scale,0xff30483d,1.67f,valley);l.setColor(0xbbe4ece9);l.setStrokeWidth(Math.max(2,w*.0014f));Path cap=new Path();for(int i=0;i<=18;i++){float x=w*i/18f,y=hz-h*scale*(.05f+.13f*(float)Math.abs(Math.sin(i*1.67+route*.012)));if(i==0)cap.moveTo(x,y);else cap.lineTo(x,y);}c.drawPath(cap,l);f.setColor(0xff1f362c);for(int i=0;i<48;i++){float x=(i*71+route*5)%Math.max(1,w),base=hz+h*(.018f+(i%6)*.011f),s=2+(i%4);p.reset();p.moveTo(x,base-s*4);p.lineTo(x-s,base);p.lineTo(x+s,base);p.close();c.drawPath(p,f);}}
 private void mountainLayer(Canvas c,int w,int h,float hz,float scale,int col,float freq,boolean valley){p.reset();p.moveTo(0,h);for(int i=0;i<=22;i++){float x=w*i/22f,y=hz-h*scale*(.035f+.13f*(float)Math.abs(Math.sin(i*freq+route*.010)));if(valley&&i>9&&i<13)y+=h*.12f;p.lineTo(x,y);}p.lineTo(w,h);p.close();f.setColor(col);c.drawPath(p,f);}
 private void coast(Canvas c,int w,int h,float hz,float s){mountains(c,w,h,hz,s,false);water(c,w,h,hz+h*.07f);}private void lake(Canvas c,int w,int h,float hz){mountains(c,w,h,hz,.56f,true);water(c,w,h,hz+h*.12f);}
 private void water(Canvas c,int w,int h,float top){f.setShader(new LinearGradient(0,top,0,h,0xff3f839f,0xff082b42,Shader.TileMode.CLAMP));c.drawRect(0,top,w,h,f);f.setShader(null);for(int row=0;row<18;row++){float y=top+(h-top)*(row+.5f)/18f;Path wp=new Path();wp.moveTo(0,y);for(int x=0;x<=w;x+=18)wp.lineTo(x,y+(float)Math.sin(x*.035+route*.08+row*.61)*(1+row*.12f));l.setColor(row%3==0?0x55d5eff7:0x248abbd0);l.setStrokeWidth(1);c.drawPath(wp,l);}for(int i=0;i<28;i++){float x=(i*101+route*9)%Math.max(1,w),y=top+(h-top)*(.12f+((i*31)%75)/100f);f.setColor(0x3fffffff);c.drawOval(x,y,x+10+i%20,y+2,f);}}
 private void road(Canvas c,int w,int h,float hz){l.setColor(0xff6f7472);l.setStrokeWidth(Math.max(12,w*.018f));p.reset();p.moveTo(w*.10f,h);p.cubicTo(w*.38f,h*.72f,w*.32f,h*.60f,w*.61f,hz+h*.06f);c.drawPath(p,l);l.setColor(0xffe8d15a);l.setStrokeWidth(2);c.drawPath(p,l);}
 private static float norm(float a){a%=360;if(a<0)a+=360;return a;}private static float angleError(float h,float t){float d=t-h;while(d>180)d-=360;while(d<-180)d+=360;return d;}private static float clamp(float v,float lo,float hi){return Math.max(lo,Math.min(hi,v));}private static float lerp(float a,float b,float t){return a+(b-a)*t;}
}
